import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import express, {
  Router,
  type Request,
  type Response,
  type NextFunction,
} from "express";
import { safeEqual, registerSecret } from "./security.js";

export interface OwnerProfile {
  email: string;
  name?: string;
  picture?: string;
  expiresAt: number;
}

export interface GeneratedKeyEntry {
  id: string;
  key: string;
  prefix: string;
  label: string;
  createdAt: number;
  lastUsedAt?: number;
}

// In-memory registry of dynamic keys generated by the signed-in owner
const dynamicApiKeys = new Map<string, GeneratedKeyEntry>();
const revokedKeyIds = new Set<string>();

const KEYS_FILE = path.resolve(process.cwd(), "data", ".krix_keys.json");
const SECRET_FILE = path.resolve(process.cwd(), "data", ".krix_session_secret");

function saveKeysToDisk(): void {
  try {
    fs.mkdirSync(path.dirname(KEYS_FILE), { recursive: true });
    const payload = {
      keys: Array.from(dynamicApiKeys.entries()),
      revoked: Array.from(revokedKeyIds),
    };
    fs.writeFileSync(KEYS_FILE, JSON.stringify(payload, null, 2), "utf-8");
  } catch {}
}

function loadKeysFromDisk(): void {
  try {
    if (fs.existsSync(KEYS_FILE)) {
      const data = JSON.parse(fs.readFileSync(KEYS_FILE, "utf-8"));
      if (Array.isArray(data.keys)) {
        for (const [id, entry] of data.keys) {
          dynamicApiKeys.set(id, entry);
          if (entry.key) registerSecret(entry.key);
        }
      }
      if (Array.isArray(data.revoked)) {
        for (const r of data.revoked) revokedKeyIds.add(r);
      }
    }
  } catch {}
}
loadKeysFromDisk();

function getSessionSecret(): string {
  if (process.env.SESSION_SECRET) return process.env.SESSION_SECRET;
  if (process.env.AUTH_SECRET) return process.env.AUTH_SECRET;
  if (process.env.MCP_API_KEY) return process.env.MCP_API_KEY;

  try {
    if (fs.existsSync(SECRET_FILE)) {
      const stored = fs.readFileSync(SECRET_FILE, "utf-8").trim();
      if (stored) return stored;
    }
    const gen = crypto.randomBytes(32).toString("hex");
    fs.mkdirSync(path.dirname(SECRET_FILE), { recursive: true });
    fs.writeFileSync(SECRET_FILE, gen, "utf-8");
    return gen;
  } catch {
    return "krix-default-session-secret-change-in-prod";
  }
}

function signCookiePayload(payload: string): string {
  const hmac = crypto.createHmac("sha256", getSessionSecret());
  hmac.update(payload);
  const sig = hmac.digest("base64url");
  return `${payload}.${sig}`;
}

function verifyCookiePayload(cookieValue: string): string | null {
  const parts = cookieValue.split(".");
  if (parts.length !== 2) return null;
  const [payload, sig] = parts;
  const hmac = crypto.createHmac("sha256", getSessionSecret());
  hmac.update(payload);
  const expectedSig = hmac.digest("base64url");
  if (!safeEqual(sig, expectedSig)) return null;
  return payload;
}

export function parseOwnerCookie(req: Request): OwnerProfile | null {
  const rawCookie = req.headers.cookie;
  if (!rawCookie) return null;
  const match = rawCookie.match(/(?:^|;\s*)krix_session=([^;]+)/);
  if (!match) return null;

  try {
    const rawVal = decodeURIComponent(match[1]);
    const payloadJson = verifyCookiePayload(rawVal);
    if (!payloadJson) return null;

    const data = JSON.parse(
      Buffer.from(payloadJson, "base64url").toString("utf-8"),
    ) as OwnerProfile;
    if (
      !data.email ||
      typeof data.expiresAt !== "number" ||
      Date.now() > data.expiresAt
    ) {
      return null;
    }

    if (!isAuthorizedEmail(data.email)) {
      return null;
    }

    return data;
  } catch {
    return null;
  }
}

export function isAuthorizedEmail(email: string): boolean {
  const owner = (
    process.env.OWNER_EMAIL ||
    process.env.GOOGLE_ALLOWED_EMAIL ||
    ""
  )
    .trim()
    .toLowerCase();
  const allowed = (process.env.ALLOWED_EMAILS || "")
    .split(",")
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);

  const target = email.trim().toLowerCase();
  if (owner && target === owner) return true;
  if (allowed.includes(target)) return true;
  // If neither OWNER_EMAIL nor ALLOWED_EMAILS is configured, require explicit configuration
  return false;
}

export function isAuthorizedApiKey(candidateKey?: string | null): boolean {
  if (!candidateKey) return false;
  const primaryKey = process.env.MCP_API_KEY;
  if (primaryKey && safeEqual(candidateKey, primaryKey)) {
    return true;
  }

  for (const entry of dynamicApiKeys.values()) {
    if (safeEqual(candidateKey, entry.key)) {
      entry.lastUsedAt = Date.now();
      return true;
    }
  }

  // Stateless signed key verification: survives Render container restarts / redeploys!
  if (candidateKey.startsWith("krix_key_")) {
    const parts = candidateKey.slice("krix_key_".length).split(".");
    if (parts.length === 2) {
      const [b64, sig] = parts;
      const expected = crypto
        .createHmac("sha256", getSessionSecret())
        .update(b64)
        .digest("base64url");
      if (safeEqual(sig, expected)) {
        try {
          const payload = JSON.parse(
            Buffer.from(b64, "base64url").toString("utf-8"),
          );
          if (payload && payload.id && !revokedKeyIds.has(payload.id)) {
            return true;
          }
        } catch {}
      }
    }
  }

  return false;
}

export function createDynamicKey(
  label: string = "Generated Key",
): GeneratedKeyEntry {
  const id = crypto.randomUUID();
  const payload = JSON.stringify({ id, label, iat: Date.now() });
  const b64 = Buffer.from(payload).toString("base64url");
  const sig = crypto
    .createHmac("sha256", getSessionSecret())
    .update(b64)
    .digest("base64url");
  const raw = `krix_key_${b64}.${sig}`;
  registerSecret(raw);
  const entry: GeneratedKeyEntry = {
    id,
    key: raw,
    prefix: raw.slice(0, 16),
    label,
    createdAt: Date.now(),
  };
  dynamicApiKeys.set(id, entry);
  saveKeysToDisk();
  return entry;
}

export function listDynamicKeys(): Omit<GeneratedKeyEntry, "key">[] {
  return [...dynamicApiKeys.values()].map(({ key, ...rest }) => rest);
}

export function revokeDynamicKey(id: string): boolean {
  revokedKeyIds.add(id);
  const deleted = dynamicApiKeys.delete(id);
  saveKeysToDisk();
  return deleted;
}

export function getPublicBaseUrl(req: Request): string {
  if (process.env.PUBLIC_BASE_URL) {
    return process.env.PUBLIC_BASE_URL.replace(/\/+$/, "");
  }
  const protoRaw = (req.headers["x-forwarded-proto"] as string)
    ?.split(",")[0]
    .trim()
    .toLowerCase();
  const proto =
    protoRaw === "http" || protoRaw === "https"
      ? protoRaw
      : req.protocol === "http"
        ? "http"
        : "https";
  const host = req.get("host") || "localhost:3000";
  return `${proto}://${host}`;
}

export function requireOwnerAuth(
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  const owner = parseOwnerCookie(req);
  if (!owner) {
    if (req.xhr || req.headers.accept?.includes("application/json")) {
      res.status(401).json({
        error: "Authentication required. Please sign in with Google.",
      });
      return;
    }
    const returnTo = encodeURIComponent(req.originalUrl || "/");
    res.redirect(`/auth/google?returnTo=${returnTo}`);
    return;
  }
  (req as any).owner = owner;
  next();
}

export function createGoogleAuthRouter(): Router {
  const router = Router();

  // GET /auth/google - initiates OAuth 2.0 flow
  router.get("/google", (req: Request, res: Response): void => {
    const clientId = process.env.GOOGLE_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
    const base = getPublicBaseUrl(req);
    const redirectUri = `${base}/auth/google/callback`;

    if (!clientId || !clientSecret) {
      res.status(503).setHeader("Content-Type", "text/html; charset=utf-8")
        .send(`
        <!DOCTYPE html>
        <html lang="en">
        <head>
          <meta charset="utf-8">
          <title>Google Authentication Not Configured - Krix</title>
          <style>
            body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #0d1117; color: #c9d1d9; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; }
            .box { background: #161b22; border: 1px solid #30363d; border-radius: 12px; padding: 32px; max-width: 480px; box-shadow: 0 8px 24px rgba(0,0,0,0.4); }
            h1 { font-size: 20px; color: #f85149; margin-top: 0; }
            p { font-size: 14px; line-height: 1.6; color: #8b949e; }
            code { background: #0d1117; border: 1px solid #30363d; border-radius: 4px; padding: 2px 6px; color: #58a6ff; }
            a { color: #58a6ff; text-decoration: none; }
          </style>
        </head>
        <body>
          <div class="box">
            <h1>Google Authentication Not Configured</h1>
            <p>To enable secure single-user sign in, configure the following environment variables in your server configuration:</p>
            <p><code>GOOGLE_CLIENT_ID</code><br><code>GOOGLE_CLIENT_SECRET</code><br><code>OWNER_EMAIL</code></p>
            <p><a href="/">&larr; Return to Krix Portal</a></p>
          </div>
        </body>
        </html>
      `);
      return;
    }

    const returnTo =
      typeof req.query.returnTo === "string" ? req.query.returnTo : "/";
    const stateObj = {
      nonce: crypto.randomBytes(16).toString("hex"),
      returnTo:
        returnTo.startsWith("/") && !returnTo.startsWith("//") ? returnTo : "/",
    };
    const state = Buffer.from(JSON.stringify(stateObj)).toString("base64url");

    res.cookie("krix_oauth_state", state, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 10 * 60 * 1000,
      path: "/auth",
    });

    const googleAuthUrl = new URL(
      "https://accounts.google.com/o/oauth2/v2/auth",
    );
    googleAuthUrl.searchParams.set("client_id", clientId);
    googleAuthUrl.searchParams.set("redirect_uri", redirectUri);
    googleAuthUrl.searchParams.set("response_type", "code");
    googleAuthUrl.searchParams.set("scope", "openid email profile");
    googleAuthUrl.searchParams.set("state", state);
    googleAuthUrl.searchParams.set("access_type", "online");
    googleAuthUrl.searchParams.set("prompt", "select_account");

    res.redirect(googleAuthUrl.toString());
  });

  // GET /auth/google/callback - exchanges code and sets session
  router.get(
    "/google/callback",
    async (req: Request, res: Response): Promise<void> => {
      const code = req.query.code as string;
      const state = req.query.state as string;
      const err = req.query.error as string;

      if (err) {
        res
          .status(400)
          .send(`Google Authentication Error: ${encodeURIComponent(err)}`);
        return;
      }

      const stateCookie = (req.headers.cookie || "").match(
        /(?:^|;\s*)krix_oauth_state=([^;]+)/,
      )?.[1];
      if (!state || !stateCookie || state !== stateCookie) {
        res
          .status(403)
          .send("State validation failed. Please try logging in again.");
        return;
      }

      let returnTo = "/";
      try {
        const parsed = JSON.parse(
          Buffer.from(state, "base64url").toString("utf-8"),
        );
        if (parsed.returnTo && typeof parsed.returnTo === "string")
          returnTo = parsed.returnTo;
      } catch {}

      const clientId = process.env.GOOGLE_CLIENT_ID;
      const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
      const base = getPublicBaseUrl(req);
      const redirectUri = `${base}/auth/google/callback`;

      try {
        const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            code,
            client_id: clientId || "",
            client_secret: clientSecret || "",
            redirect_uri: redirectUri,
            grant_type: "authorization_code",
          }).toString(),
        });

        if (!tokenRes.ok) {
          const errorText = await tokenRes.text();
          console.error("[auth] Google token exchange failed:", errorText);
          res
            .status(502)
            .send("Failed to exchange authorization code with Google.");
          return;
        }

        const tokenData = (await tokenRes.json()) as any;
        const accessToken = tokenData.access_token;

        const userRes = await fetch(
          "https://www.googleapis.com/oauth2/v3/userinfo",
          {
            headers: { Authorization: `Bearer ${accessToken}` },
          },
        );

        if (!userRes.ok) {
          res.status(502).send("Failed to retrieve user profile from Google.");
          return;
        }

        const userData = (await userRes.json()) as any;
        const email = userData.email as string;
        const emailVerified = userData.email_verified as boolean;

        if (!email || !emailVerified) {
          res.status(403).send("Google account email is not verified.");
          return;
        }

        if (!isAuthorizedEmail(email)) {
          res.status(403).setHeader("Content-Type", "text/html; charset=utf-8")
            .send(`
          <!DOCTYPE html>
          <html lang="en">
          <head>
            <meta charset="utf-8">
            <title>Access Denied - Krix</title>
            <style>
              body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #0d1117; color: #c9d1d9; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; }
              .card { background: #161b22; border: 1px solid #f85149; border-radius: 12px; padding: 32px; max-width: 460px; box-shadow: 0 8px 24px rgba(0,0,0,0.4); text-align: center; }
              h1 { color: #f85149; margin-top: 0; font-size: 20px; }
              p { color: #8b949e; font-size: 14px; line-height: 1.5; }
              code { background: #0d1117; border: 1px solid #30363d; border-radius: 4px; padding: 2px 6px; color: #f0f6fc; }
              a { color: #58a6ff; text-decoration: none; display: inline-block; margin-top: 16px; font-size: 14px; }
            </style>
          </head>
          <body>
            <div class="card">
              <h1>403 Forbidden: Unauthorized Account</h1>
              <p>Signed in as <code>${encodeURIComponent(email)}</code>.</p>
              <p>This instance is configured for single-user owner access only. Your Google account is not authorized.</p>
              <a href="/auth/google">&larr; Sign in with another Google account</a>
            </div>
          </body>
          </html>
        `);
          return;
        }

        const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
        const profile: OwnerProfile = {
          email,
          name: userData.name || email.split("@")[0],
          picture: userData.picture,
          expiresAt: Date.now() + thirtyDaysMs,
        };

        const payloadStr = Buffer.from(JSON.stringify(profile)).toString(
          "base64url",
        );
        const cookieVal = signCookiePayload(payloadStr);

        res.cookie("krix_session", cookieVal, {
          httpOnly: true,
          secure: process.env.NODE_ENV === "production",
          sameSite: "lax",
          maxAge: thirtyDaysMs,
          expires: new Date(Date.now() + thirtyDaysMs),
          path: "/",
        });

        res.clearCookie("krix_oauth_state", { path: "/auth" });
        res.redirect(returnTo);
      } catch (e: any) {
        console.error("[auth] Google OAuth flow failed:", e);
        res.status(500).send("Authentication service error.");
      }
    },
  );

  // GET /auth/logout
  router.get("/logout", (_req: Request, res: Response): void => {
    res.clearCookie("krix_session", { path: "/" });
    res.redirect("/");
  });

  // GET /auth/session - returns current session status
  router.get("/session", (req: Request, res: Response): void => {
    const owner = parseOwnerCookie(req);
    if (!owner) {
      res.json({ authenticated: false });
      return;
    }
    res.json({
      authenticated: true,
      owner: {
        email: owner.email,
        name: owner.name,
        picture: owner.picture,
      },
      keys: listDynamicKeys(),
    });
  });

  // POST /auth/keys - generate a dynamic API key
  router.post(
    "/keys",
    requireOwnerAuth,
    (req: Request, res: Response): void => {
      const label =
        typeof req.body?.label === "string"
          ? req.body.label.trim().slice(0, 50)
          : "Personal Key";
      const entry = createDynamicKey(label);
      res.status(201).json({
        id: entry.id,
        key: entry.key,
        prefix: entry.prefix,
        label: entry.label,
        createdAt: entry.createdAt,
      });
    },
  );

  // DELETE /auth/keys/:id - revoke a dynamic API key
  router.delete(
    "/keys/:id",
    requireOwnerAuth,
    (req: Request, res: Response): void => {
      const id = req.params.id as string;
      const deleted = revokeDynamicKey(id);
      res.json({ success: deleted });
    },
  );

  return router;
}
